#[verus::spec]
fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    // Precondition: n and m must be greater than 0
    // Requires: n > 0 && m > 0
    assert!(n > 0 && m > 0);
    
    // Create an n-by-m matrix initialized with 0.0
    let mut matrix = vec![vec![0.0; m]; n]; 

    // Invariant: At the start of each iteration of the outer loop, 
    // all elements in matrix[0..i][0..m] are correctly initialized
    // and matrix[i][j] is 0.0 for j > (i + k)
    #[verus::invariant]
    fn invariant(i: usize, n: usize, m: usize, k: i32, matrix: &Vec<Vec<f64>>) {
        assert!(i <= n);
        for x in 0..i {
            for y in 0..m {
                assert!(matrix[x][y] == 1.0 || (y > (x as i32 + k) && matrix[x][y] == 0.0));
            }
        }
    }

    // Loop from 0 to n
    for i in 0..n {
        // Loop from 0 to m
        for j in 0..m {
            // Set the value to 1.0 if the condition is met
            if j <= (i as i32 + k) {
                matrix[i][j] = 1.0; 
            }
            // Ensure that the invariant holds after each inner loop iteration
            invariant(i, n, m, k, &matrix);
        }
    }

    // Postcondition: The matrix is filled correctly according to the rules defined
    // Ensures: For all i in 0..n and j in 0..m, if j <= (i + k), then matrix[i][j] == 1.0
    for i in 0..n {
        for j in 0..m {
            if j <= (i as i32 + k) {
                assert!(matrix[i][j] == 1.0);
            } else {
                assert!(matrix[i][j] == 0.0);
            }
        }
    }

    matrix // Return the constructed matrix
}

